:root {
  color-scheme: dark;
  --ink: #0b0809;
  --brown-950: #1b1110;
  --brown-900: #261716;
  --brown-700: #4b2d26;
  --brown-500: #765044;
  --bone: #e8d4b7;
  --muted: #a78b7c;
  --blood: #9e2d2b;
  --red: #d24a3f;
  --gold: #e2ad47;
  --panel: rgba(27, 17, 16, 0.94);
}

* {
  box-sizing: border-box;
}

html,
body {
  width: 100%;
  min-height: 100%;
  margin: 0;
}

body {
  display: grid;
  place-items: center;
  overflow-x: hidden;
  padding: 20px;
  color: var(--bone);
  font-family: "Courier New", Courier, monospace;
  background:
    radial-gradient(circle at 50% 20%, #38201d 0, #1a1010 43%, #090708 100%),
    repeating-linear-gradient(0deg, transparent 0 5px, rgba(255, 255, 255, 0.012) 5px 6px);
}

body::before {
  position: fixed;
  inset: 0;
  z-index: -1;
  content: "";
  opacity: 0.16;
  pointer-events: none;
  background-image:
    repeating-linear-gradient(90deg, rgba(255, 255, 255, 0.025) 0 1px, transparent 1px 7px),
    repeating-linear-gradient(0deg, rgba(255, 255, 255, 0.02) 0 1px, transparent 1px 7px);
}

#game-shell {
  width: min(960px, 100%);
}

#canvas-wrap {
  position: relative;
  width: 100%;
  overflow: hidden;
  border: 4px solid #593a31;
  border-radius: 3px;
  background: #120c0c;
  box-shadow:
    0 0 0 2px #0b0808,
    0 18px 55px rgba(0, 0, 0, 0.72),
    inset 0 0 35px rgba(0, 0, 0, 0.85);
}

#gameCanvas {
  display: block;
  width: 100%;
  height: auto;
  aspect-ratio: 3 / 2;
  outline: none;
  image-rendering: pixelated;
  image-rendering: crisp-edges;
  cursor: crosshair;
}

#gameCanvas:focus-visible {
  box-shadow: inset 0 0 0 3px var(--gold);
}

.overlay {
  position: absolute;
  inset: 0;
  z-index: 10;
  display: grid;
  place-items: center;
  padding: 24px;
  background: rgba(8, 5, 6, 0.74);
  backdrop-filter: blur(2px);
}

.overlay[hidden] {
  display: none;
}

.panel {
  width: min(520px, 92%);
  padding: 34px 38px 30px;
  text-align: center;
  border: 3px solid var(--brown-500);
  border-radius: 2px;
  background: var(--panel);
  box-shadow:
    inset 0 0 0 3px #1a0f0e,
    inset 0 0 0 5px #513029,
    0 14px 35px rgba(0, 0, 0, 0.75);
}

.panel-kicker {
  margin: 0 0 8px;
  color: var(--red);
  font-size: 0.76rem;
  font-weight: 900;
  letter-spacing: 0.38em;
}

.panel h1 {
  margin: 0 0 14px;
  color: var(--bone);
  font-size: clamp(2rem, 7vw, 3.4rem);
  line-height: 0.95;
  text-shadow: 3px 3px 0 #4a201e;
}

.panel p:not(.panel-kicker) {
  margin: 0 auto 24px;
  color: #cbb49f;
  line-height: 1.55;
}

.panel small {
  display: block;
  margin-top: 18px;
  color: var(--muted);
}

.button-row {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 12px;
}

button {
  min-height: 44px;
  padding: 10px 18px;
  color: #160e0d;
  font: 900 0.84rem/1.1 "Courier New", Courier, monospace;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  border: 0;
  border-radius: 0;
  background: var(--bone);
  box-shadow: 3px 3px 0 #6e4a3c;
  cursor: pointer;
}

button:hover,
button:focus-visible {
  color: #fff4dc;
  background: var(--red);
  outline: 2px solid var(--gold);
  outline-offset: 2px;
  transform: translate(-1px, -1px);
}

button:active {
  box-shadow: 1px 1px 0 #6e4a3c;
  transform: translate(1px, 1px);
}

#btn-secondary {
  color: var(--bone);
  background: #382320;
  box-shadow: 3px 3px 0 #160e0d;
}

footer {
  display: flex;
  justify-content: center;
  flex-wrap: wrap;
  gap: 7px 20px;
  padding: 14px 8px 0;
  color: #8e7568;
  font-size: 0.73rem;
  text-transform: uppercase;
}

kbd {
  padding: 2px 5px;
  color: #d8c4ae;
  font: inherit;
  font-weight: 700;
  border: 1px solid #5b4038;
  border-bottom-width: 2px;
  border-radius: 2px;
  background: #211513;
}

@media (max-width: 650px) {
  body {
    padding: 8px;
  }

  #canvas-wrap {
    border-width: 2px;
  }

  .panel {
    padding: 22px 18px;
  }

  footer {
    display: none;
  }
}

