+  }
+
+  // ---------------------------------------------------------------------------
+  // Chefe — dois padrões alternados: rajada radial e investida
+  // ---------------------------------------------------------------------------
+  class Boss extends Enemy {
+    constructor(x, y, floor) {
+      super('chaser', x, y, floor);
