+
+      if (this.phase === 'idle') {
+        this.phaseTimer -= 0;
+      }
+      if (this.phase === 'idle' && this.phaseTimer <= 0) {
+        this.attackPattern = this.attackPattern === 0 ? 1 : 0;
+      }
+    }
+
+    fireRadial(game) {
+      const count = 10 + this.floor * 2;
