  loop(time) {
    const dt = Math.min(0.033, Math.max(0, (time - this.lastTime) / 1000));
    this.lastTime = time;
    this.elapsed += dt;
    if (this.state === 'play') this.update(dt);
    this.arrowTogglePulse = Math.max(0, this.arrowTogglePulse - dt * 2);
    this.render();
    requestAnimationFrame((nextTime) => this.loop(nextTime));
  }
}

