  out.radialProjectiles = g.projectiles.length;
  out.bossHatchBefore = !!g.currentRoom.hatch;
  g.damageEnemy(boss, 999);
  out.bossAfter = {enemies:g.currentRoom.enemies.length, cleared:g.currentRoom.cleared, hatch:!!g.currentRoom.hatch};

  // Testa alçapão e avanço de andar.
  const beforeFloor = g.floor;
  if (g.currentRoom.hatch) {
    g.player.x = g.currentRoom.hatch.x;
    g.player.y = g.currentRoom.hatch.y;
    g.updateHatch();
  }
  out.nextFloor = {before:beforeFloor, after:g.floor, room:g.currentRoom.type, rooms:g.rooms.size};

  // Testa morte e pausa.
  g.player.health=1;
  g.player.invulnerable=0;
  g.player.takeDamage(1,g,g.player.x+10,g.player.y);
  out.gameover = g.state;
  out.overlay = !g.overlay.hidden;
  g.startRun(1);
  g.pause();
  out.pause = {state:g.state, overlay:!g.overlay.hidden};
  g.resume();
  out.resumed = g.state;
  return out;
})()

