+      const sub = this.ctx.createOscillator();
+      const filter = this.ctx.createBiquadFilter();
+      const lfo = this.ctx.createOscillator();
+      const lfoGain = this.ctx.createGain();
+      const gain = this.ctx.createGain();
+
+      osc.type = 'square';
+      osc.frequency.setValueAtTime(freq, time);
+      sub.type = 'triangle';
+      sub.frequency.setValueAtTime(freq / 2, time);
+
+      filter.type = 'lowpass';
+      filter.frequency.setValueAtTime(360, time);
+      filter.Q.value = 7;
+      lfo.type = 'sine';
+      lfo.frequency.setValueAtTime(4.5 + (step % 4) * 1.7, time);
+      lfoGain.gain.value = 310;
+      lfo.connect(lfoGain);
+      lfoGain.connect(filter.frequency);
+
+      gain.gain.setValueAtTime(0.0001, time);
+      gain.gain.linearRampToValueAtTime(0.17, time + 0.008);
+      gain.gain.setValueAtTime(0.13, time + 0.07);
+      gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.145);
+
+      osc.connect(filter);
+      sub.connect(filter);
+      filter.connect(gain);
+      gain.connect(this.musicGain);
+
+      osc.start(time);
+      sub.start(time);
+      lfo.start(time);
+      osc.stop(time + 0.16);
+      sub.stop(time + 0.16);
+      lfo.stop(time + 0.16);
+    }
+
+    playLead(freq, time) {
+      const osc = this.ctx.createOscillator();
+      const gain = this.ctx.createGain();
+      osc.type = 'square';
+      osc.frequency.setValueAtTime(freq, time);
+      gain.gain.setValueAtTime(0.0001, time);
+      gain.gain.linearRampToValueAtTime(0.032, time + 0.006);
+      gain.gain.exponentialRampToValueAtTime(0.0001, time + 0.1);
+      osc.connect(gain);
+      gain.connect(this.musicGain);
+      osc.start(time);
+      osc.stop(time + 0.11);
+    }
