  margin-top: 4px;
}

footer .footer-audio {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  min-height: 0;
  padding: 2px 7px;
  color: #b49a88;
  font: inherit;
  letter-spacing: 0;
  text-transform: uppercase;
  border: 1px solid #5b4038;
  background: transparent;
  box-shadow: none;
}

footer .footer-audio:hover,
footer .footer-audio:focus-visible {
  color: var(--bone);
  background: #2a1916;
  box-shadow: none;
  transform: none;
}

